"""Tests of navera_lite/vehicle.py (mission 03). Written for the course; it is not NAVERA code."""
import math

import pytest

from navera_lite.vehicle import (VEHICLES, FixedWing, Multirotor, Vehicle, endurance_s, ground_velocity,
                                 heading_for_track, heading_vector, wind_components)


def test_heading_vector_is_clockwise_from_north():
    e, n = heading_vector(90.0)
    assert e == pytest.approx(1.0) and n == pytest.approx(0.0, abs=1e-12)
    e, n = heading_vector(225.0)
    assert (e, n) == pytest.approx((-math.sqrt(0.5), -math.sqrt(0.5)))


def test_ground_velocity_adds_the_wind():
    assert ground_velocity(10.0, 90.0, 0.0, 3.0) == pytest.approx((10.0, 3.0))


def test_wind_components_signs():
    along, cross = wind_components(0.0, 2.0, -5.0)
    assert along == pytest.approx(-5.0) and cross == pytest.approx(2.0)


def test_heading_for_track_crabs_into_the_wind():
    h, gs = heading_for_track(0.0, 10.0, 6.0, 0.0)
    assert h == pytest.approx(323.1301, abs=1e-3) and gs == pytest.approx(8.0)
    assert 0.0 <= heading_for_track(10.0, 12.0, 0.0, 0.0)[0] < 360.0


@pytest.mark.parametrize("args", [(0.0, 10.0, 11.0, 0.0), (0.0, 10.0, 0.0, -10.0)])
def test_heading_for_track_refuses_impossible_wind(args):
    with pytest.raises(ValueError):
        heading_for_track(*args)


def test_endurance():
    assert endurance_s(50.0, 200.0, 0.1) == pytest.approx(810.0)
    for bad in [(0.0, 200.0), (50.0, 0.0), (50.0, 200.0, 1.0), (50.0, 200.0, -0.1)]:
        with pytest.raises(ValueError):
            endurance_s(*bad)


def test_vehicle_classes():
    v = Vehicle("rover", 2.0, 3.0, 400.0, 100.0)
    assert v.max_speed_mps == 3.0 and v.endurance_s() == pytest.approx(11520.0)
    assert v.range_m(-0.5) == pytest.approx(17280.0) and v.range_m(-5.0) == 0.0
    with pytest.raises(ValueError):
        Vehicle("bad", 0.0, 3.0, 400.0, 100.0)
    with pytest.raises(ValueError):
        Vehicle("bad", 4.0, 3.0, 400.0, 100.0)
    w = FixedWing("glider", 15.0, 25.0, 60.0, 80.0, 9.0)
    assert isinstance(w, Vehicle) and w.stall_mps == 9.0 and w.endurance_s() == pytest.approx(2160.0)
    with pytest.raises(ValueError):
        FixedWing("glider", 9.0, 25.0, 60.0, 80.0, 9.0)
    assert Multirotor("quad", 12.0, 20.0, 160.0, 350.0).hover_s(300.0) == pytest.approx(1536.0)
    assert VEHICLES["drone"] == 30.0
